const { chromium } = require('playwright')

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } })
  const errors = []
  page.on('pageerror', (e) => errors.push(String(e)))

  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', {
    waitUntil: 'domcontentloaded',
    timeout: 60000
  })
  await page.waitForSelector('select[aria-label="交易面板年份"]', { timeout: 30000 })
  await page.waitForTimeout(1200)

  const yearSel = 'select[aria-label="交易面板年份"]'
  const monthSel = 'select[aria-label="交易面板月份"]'
  const now = new Date()
  const currentYear = now.getFullYear()
  const currentMonth = now.getMonth() + 1

  const yearOpts = await page.$$eval(yearSel + ' option', (els) =>
    els.map((e) => ({ value: e.value, text: e.textContent.trim() }))
  )
  const monthOpts = await page.$$eval(monthSel + ' option', (els) => els.map((e) => e.value))

  console.log('当前年月:', currentYear, currentMonth)
  console.log('年份选项:', JSON.stringify(yearOpts))
  console.log('月份选项:', JSON.stringify(monthOpts))

  const histYear = String(currentYear - 1)
  await page.selectOption(yearSel, histYear)
  await page.waitForTimeout(250)
  const histMonths = await page.$$eval(monthSel + ' option', (els) => els.map((e) => e.value))
  console.log('切到历史年(' + histYear + ')月份选项:', JSON.stringify(histMonths))

  await page.selectOption(monthSel, '12月')
  await page.selectOption(yearSel, String(currentYear))
  await page.waitForTimeout(250)
  const clamped = await page.$eval(monthSel, (el) => el.value)
  const backMonths = await page.$$eval(monthSel + ' option', (els) => els.map((e) => e.value))
  console.log('切回当前年后选中月份:', clamped, '月份选项:', JSON.stringify(backMonths))
  console.log('页面错误:', JSON.stringify(errors))

  const ok =
    yearOpts.length === 4 &&
    yearOpts[0].value === String(currentYear) &&
    yearOpts.every((o) => Number(o.value) <= currentYear) &&
    monthOpts.length === currentMonth &&
    monthOpts[monthOpts.length - 1] === currentMonth + '月' &&
    histMonths.length === 12 &&
    clamped === currentMonth + '月' &&
    backMonths.length === currentMonth

  console.log('RESULT', ok ? 'PASS' : 'FAIL')
  await browser.close()
  process.exit(ok ? 0 : 1)
})().catch((e) => {
  console.error(e)
  process.exit(1)
})
